CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, model TEXT NOT NULL, color TEXT NOT NULL, capacity TEXT NOT NULL, url TEXT NOT NULL, active INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS stores (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS watches (id TEXT PRIMARY KEY, name TEXT NOT NULL, productIds TEXT NOT NULL, storeIds TEXT NOT NULL, enabled INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS states (id TEXT PRIMARY KEY, product_id TEXT NOT NULL, store_id TEXT NOT NULL, status TEXT NOT NULL, confirmed TEXT, checked_at INTEGER, attempted_at INTEGER NOT NULL, segment_id TEXT);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, product_id TEXT NOT NULL, store_id TEXT NOT NULL, at INTEGER NOT NULL, kind TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_at ON events(at);
CREATE TABLE IF NOT EXISTS intervals (id TEXT PRIMARY KEY, product_id TEXT NOT NULL, store_id TEXT NOT NULL, start INTEGER NOT NULL, end INTEGER NOT NULL, status TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS intervals_end ON intervals(end);
CREATE TABLE IF NOT EXISTS rounds (id TEXT PRIMARY KEY, at INTEGER NOT NULL, status TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS rounds_at ON rounds(at);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, created_at INTEGER NOT NULL, attempts INTEGER NOT NULL, next_at INTEGER NOT NULL, status TEXT NOT NULL, message TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS notifications_due ON notifications(status, next_at);
CREATE TABLE IF NOT EXISTS diagnostics (id TEXT PRIMARY KEY, at INTEGER NOT NULL, message TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS diagnostics_at ON diagnostics(at);
CREATE TABLE IF NOT EXISTS locks (id TEXT PRIMARY KEY, owner TEXT, expires INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO locks(id, expires) VALUES ('monitor', 0);
CREATE TABLE IF NOT EXISTS login_limits (id TEXT PRIMARY KEY, failures INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS commit_guard (id TEXT PRIMARY KEY, valid INTEGER NOT NULL CHECK(valid = 1));
